#!/usr/bin/env bash
# NIRUPI tune — small, reversible, hardware-aware system tuning.
#
#   nirupi tune status          show the current values
#   nirupi tune plan            show exactly what apply would change
#   nirupi tune apply [--yes]   write /etc/sysctl.d/90-nirupi.conf
#   nirupi tune revert [--yes]  remove it and reload sysctl
#
# This deliberately does not change CPU governors, I/O schedulers or zram
# behind your back. Those are hardware-specific and are reported as hints.
set -Eeuo pipefail

CONF=/etc/sysctl.d/90-nirupi.conf
JOURNAL=/etc/systemd/journald.conf.d/90-nirupi.conf
DISTRO=unknown
[[ -r /etc/os-release ]] && . /etc/os-release && DISTRO="${ID:-unknown}"

have(){ command -v "$1" >/dev/null 2>&1; }
if [[ ${EUID:-$(id -u)} -eq 0 ]]; then sudo(){ "$@"; }; fi
say(){ printf '%s\n' "$*"; }
warn(){ printf '[WARN] %s\n' "$*" >&2; }
die(){ printf '[ERROR] %s\n' "$*" >&2; exit 1; }

need_root(){
 if [[ $(id -u) -eq 0 ]]; then return 0; fi
 have sudo || die 'sudo is required for tune apply/revert'
}

confirm(){
 local answer
 [[ ${1:-0} == 1 ]] && return 0
 [[ -t 0 ]] || die 'Refusing a non-interactive change without --yes'
 printf 'Type TUNE to apply these changes: '
 read -r answer
 [[ $answer == TUNE ]] || die 'Cancelled'
}

swap_is_zram(){
 if have swapon && swapon --show=NAME --noheadings 2>/dev/null | grep -q 'zram'; then return 0; fi
 grep -qs 'zram' /proc/swaps 2>/dev/null
}

bbr_available(){
 [[ -r /proc/sys/net/ipv4/tcp_available_congestion_control ]] || return 1
 grep -qw bbr /proc/sys/net/ipv4/tcp_available_congestion_control
}

desired_values(){
 SWAPPINESS=10
 swap_is_zram && SWAPPINESS=100
 VFS_CACHE_PRESSURE=50
 DIRTY_BACKGROUND_RATIO=5
 DIRTY_RATIO=10
 INOTIFY_WATCHES=524288
 PAGE_CLUSTER=3
 swap_is_zram && PAGE_CLUSTER=0
 BBR=0
 bbr_available && BBR=1
 return 0
}

current_value(){
 local f="$1"
 [[ -r $f ]] && cat "$f" 2>/dev/null || printf '?'
}

show_hardware(){
 say "Distribution : $DISTRO"
 say "Kernel       : $(uname -r)"
 say "CPU governor : $(current_value /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)"
 if have swapon; then
  say "Swap         : $(swapon --show=NAME,TYPE,SIZE --noheadings 2>/dev/null | tr '\n' ' ' || true)"
 fi
 if have zramctl; then
  say "zram         : $(zramctl --noheadings --output NAME,DISKSIZE,ALGORITHM 2>/dev/null | tr '\n' ' ' || true)"
 fi
 if have findmnt; then
  local root_src root_fstype
  root_src="$(findmnt -n -o SOURCE / 2>/dev/null || true)"
  root_fstype="$(findmnt -n -o FSTYPE / 2>/dev/null || true)"
  say "Root         : ${root_src:-?} (${root_fstype:-?})"
 fi
 if have systemctl; then
  say "fstrim.timer : $(systemctl is-enabled fstrim.timer 2>/dev/null || printf 'not-enabled')"
  say "journald cap : $([[ -f $JOURNAL ]] && printf configured || printf 'not-configured')"
 fi
}

cmd_status(){
 desired_values
 say 'NIRUPI tune status'
 show_hardware
 say ''
 say "vm.swappiness                : $(current_value /proc/sys/vm/swappiness) (target $SWAPPINESS)"
 say "vm.vfs_cache_pressure        : $(current_value /proc/sys/vm/vfs_cache_pressure) (target $VFS_CACHE_PRESSURE)"
 say "vm.dirty_background_ratio    : $(current_value /proc/sys/vm/dirty_background_ratio) (target $DIRTY_BACKGROUND_RATIO)"
 say "vm.dirty_ratio               : $(current_value /proc/sys/vm/dirty_ratio) (target $DIRTY_RATIO)"
 say "vm.page-cluster              : $(current_value /proc/sys/vm/page-cluster) (target $PAGE_CLUSTER)"
 say "fs.inotify.max_user_watches  : $(current_value /proc/sys/fs/inotify/max_user_watches) (target $INOTIFY_WATCHES)"
 say "TCP congestion control       : $(current_value /proc/sys/net/ipv4/tcp_congestion_control) (target $([[ $BBR == 1 ]] && printf bbr || printf unchanged))"
 say "config file                  : $([[ -f $CONF ]] && printf present || printf absent)"
}

cmd_plan(){
 desired_values
 say 'NIRUPI tune plan (read-only)'
 show_hardware
 say ''
 say "Would write $CONF:"
 say "  vm.swappiness = $SWAPPINESS"
 say "  vm.vfs_cache_pressure = $VFS_CACHE_PRESSURE"
 say "  vm.dirty_background_ratio = $DIRTY_BACKGROUND_RATIO"
 say "  vm.dirty_ratio = $DIRTY_RATIO"
 say "  vm.page-cluster = $PAGE_CLUSTER"
 say "  fs.inotify.max_user_watches = $INOTIFY_WATCHES"
 [[ $BBR == 1 ]] && say '  net.core.default_qdisc = fq' && say '  net.ipv4.tcp_congestion_control = bbr'
 if have systemctl; then
  say "Would cap the system journal at 200M in $JOURNAL and enable fstrim.timer"
 fi
 say ''
 if swap_is_zram; then
  say 'zram swap detected: swappiness=100 and page-cluster=0 are appropriate.'
 else
  say 'No zram swap detected. If you want compressed RAM swap, install the distro'
  say 'zram service (Void: zramen, Arch/Debian: zram-generator) and re-run tune.'
 fi
 say 'CPU governor, I/O scheduler and firmware are intentionally left alone.'
}

write_sysctl(){
 desired_values
 {
  printf '# Generated by nirupi tune. Re-run: nirupi tune apply\n'
  printf '# Remove with: nirupi tune revert\n'
  printf 'vm.swappiness = %s\n' "$SWAPPINESS"
  printf 'vm.vfs_cache_pressure = %s\n' "$VFS_CACHE_PRESSURE"
  printf 'vm.dirty_background_ratio = %s\n' "$DIRTY_BACKGROUND_RATIO"
  printf 'vm.dirty_ratio = %s\n' "$DIRTY_RATIO"
  printf 'vm.page-cluster = %s\n' "$PAGE_CLUSTER"
  printf 'fs.inotify.max_user_watches = %s\n' "$INOTIFY_WATCHES"
  if [[ $BBR == 1 ]]; then
   printf 'net.core.default_qdisc = fq\n'
   printf 'net.ipv4.tcp_congestion_control = bbr\n'
  fi
 } | sudo tee "$CONF" >/dev/null
 sudo chmod 0644 "$CONF"
 if have sysctl; then
  sudo sysctl --system >/dev/null 2>&1 || sudo sysctl -p "$CONF" >/dev/null 2>&1 || warn 'sysctl reload failed; values apply after reboot'
 fi
}

write_journal(){
 have systemctl || return 0
 systemctl list-unit-files systemd-journald.service >/dev/null 2>&1 || return 0
 sudo install -d /etc/systemd/journald.conf.d
 printf '[Journal]\nSystemMaxUse=200M\nRuntimeMaxUse=64M\n' | sudo tee "$JOURNAL" >/dev/null
 sudo systemctl restart systemd-journald >/dev/null 2>&1 || warn 'Could not restart systemd-journald'
}

enable_trim(){
 have systemctl || return 0
 systemctl list-unit-files fstrim.timer >/dev/null 2>&1 || return 0
 sudo systemctl enable --now fstrim.timer >/dev/null 2>&1 && say 'Enabled fstrim.timer' || warn 'Could not enable fstrim.timer'
}

cmd_apply(){
 local yes="${1:-0}"
 need_root
 confirm "$yes"
 write_sysctl
 write_journal
 enable_trim
 say "Applied $CONF"
 say 'Reboot is not required; sysctl was reloaded. Use `nirupi tune revert` to undo.'
}

cmd_revert(){
 local yes="${1:-0}"
 need_root
 confirm "$yes"
 sudo rm -f "$CONF" "$JOURNAL"
 have sysctl && { sudo sysctl --system >/dev/null 2>&1 || true; }
 say 'Removed NIRUPI sysctl and journald overrides.'
 say 'fstrim.timer was left as-is (it is a safe distro default).'
}

case "${1:-status}" in
 status) cmd_status;;
 plan|--dry-run|--plan) cmd_plan;;
 apply) shift || true; yes=0; [[ ${1:-} == --yes ]] && yes=1; cmd_apply "$yes";;
 revert|undo) shift || true; yes=0; [[ ${1:-} == --yes ]] && yes=1; cmd_revert "$yes";;
 -h|--help) sed -n '1,20p' "$0";;
 *) die 'Usage: nirupi tune [status|plan|apply [--yes]|revert [--yes]]';;
esac
